// --- rendering ---------------------------------------------------------------------

const fence = (lang: string, lines: string[]) => [`\`\`\`${lang}`, ...lines, '```'];

/** JSON as a person would write it: short things on one line, long things spread out. */
export function compactJson(value: unknown, indent = ''): string {
  const flat = JSON.stringify(value);
  if (flat === undefined || flat.length + indent.length <= 110 || value === null || typeof value !== 'object') return flat ?? 'null';
  const inner = `${indent}  `;
  if (Array.isArray(value)) return `[\n${value.map(v => `${inner}${compactJson(v, inner)}`).join(',\n')}\n${indent}]`;
  const entries = Object.entries(value as Record<string, unknown>).map(([k, v]) => `${inner}${JSON.stringify(k)}: ${compactJson(v, inner)}`);
  return `{\n${entries.join(',\n')}\n${indent}}`;
}

/** Examples as markdown, indented to sit inside a numbered step. Plain commands share a fence. */
function renderExamples(examples: readonly Example[], indent: string): string[] {
  const out: string[] = [];
  let plain: string[] = [];
  const flush = () => {
    if (plain.length > 0) out.push(...fence('bash', plain));
    plain = [];
  };
  for (const example of examples) {
    if (example.file === undefined && example.stdin === undefined) {
      plain.push(example.line);
      continue;
    }
    flush();
    if (example.file !== undefined) {
      const content = example.file.content;
      out.push(`\`${example.file.name}\`:`, ...(typeof content === 'string' ? fence('markdown', content.replace(/\n$/, '').split('\n')) : fence('json', compactJson(content).split('\n'))));
    }
    if (example.stdin !== undefined) out.push(...fence('bash', [`${example.line} <<'EOF'`, ...example.stdin.replace(/\n$/, '').split('\n'), 'EOF']));
    else out.push(...fence('bash', [example.line]));
  }
  flush();
  return out.map(line => (line === '' ? line : `${indent}${line}`));
}

function table(header: string[], rows: string[][]): string[] {
  const cell = (s: string) => s.replace(/\|/g, '\\|');
  return [`| ${header.join(' | ')} |`, `|${header.map(() => '---').join('|')}|`, ...rows.map(r => `| ${r.map(cell).join(' | ')} |`)];
}

